package org.myforeverpet.paradise;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
 private final PetRuntime pet=PetRuntime.get();private final PetArt art=new PetArt();private final Handler h=new Handler(Looper.getMainLooper());
 private Arcade game;private long frameAt,accum;private int zoom=2,hits=0,remaining=0,displayedStage=-1;private boolean playing=false,active=false;private long gameEnd;private float targetX=.5f,targetY=.5f;
 private TextView status,caption,clockLabel;private String clockKey="";private LinearLayout actions,zooms,footer;private View scene;private PetState cached;private long cachedAt;private PetState state(){long n=SystemClock.elapsedRealtime();if(cached==null||n-cachedAt>=250){cached=pet.snapshot();cachedAt=n;}return cached;}
 private final Runnable refresh=new Runnable(){public void run(){if(!active)return;updateClock();if(playing&&game!=null){long now=SystemClock.elapsedRealtime();accum+=Math.min(100,Math.max(0,now-frameAt));frameAt=now;while(accum>=16){game.step();accum-=16;}scene.invalidate();caption.setText(game.over?"Run complete • collect coins":"Score "+game.score+"  •  "+(game.mode==0?"Tap stars":game.mode==1?"Tap to flap":game.mode==3?"Find your pet in the crowd":"Touch left/right to steer"));}else update();h.postDelayed(this,playing&&game!=null&&!game.over?16:100);}};
 private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);pet.init(this);getWindow().setStatusBarColor(0xff17243c);getWindow().setNavigationBarColor(0xff17243c);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(0xff171b39);
 TextView title=new TextView(this);title.setText("MY FOREVER PET");title.setTextSize(20);title.setTypeface(Typeface.create("sans-serif-black",0));title.setTextColor(0xfff7edff);title.setGravity(17);root.addView(title);
 clockLabel=new TextView(this);clockLabel.setTextColor(0xffe9cba0);clockLabel.setTextSize(12);clockLabel.setGravity(17);root.addView(clockLabel);clockLabel.setOnClickListener(v->routine());updateClock();
 status=new TextView(this);status.setTextColor(0xfff5eaff);status.setTextSize(14);status.setGravity(17);root.addView(status);
 scene=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){if(playing&&game!=null){art.drawArcade(c,state(),game,SystemClock.elapsedRealtime());}else art.draw(c,state(),zoom,false,SystemClock.elapsedRealtime());}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(playing&&game!=null){if(game.over&&e.getActionMasked()==MotionEvent.ACTION_DOWN){finishGame();return true;}float z=Math.min(getWidth()/160f,getHeight()/192f);float x=(e.getX()-(getWidth()-160*z)/2)/z,y=(e.getY()-(getHeight()-192*z)/2)/z;if(e.getActionMasked()==MotionEvent.ACTION_DOWN||(game.mode==Arcade.JUMP&&e.getActionMasked()==MotionEvent.ACTION_MOVE))game.input(x,y);else if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)game.release();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&zoom==2){if(onPet(e))act(15,0);return true;}if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(pet.snapshot().stage==0){pet.action(0,0);rebuild();}else if(zoom==2){if(onPet(e))act(15,0);}else if(zoom==3){PetState p=pet.snapshot();if(p.sick)pet.action(4,0);else pet.action(5,0);update();}return true;}return true;}};
 root.addView(scene,new LinearLayout.LayoutParams(-1,0,1));
 caption=new TextView(this);caption.setGravity(17);caption.setTextColor(0xffdfd0ff);root.addView(caption);
 zooms=new LinearLayout(this);String[] names={"✦ Space","♧ Field","♡ Pet","◉ Cell"};for(int i=0;i<4;i++){final int z=i;button(zooms,names[i],()->{if(playing)finishGame();zoom=z;rebuild();});}root.addView(zooms);
 actions=new LinearLayout(this);actions.setOrientation(1);root.addView(actions);
 footer=new LinearLayout(this);button(footer,"▦ Lab",()->lab());button(footer,"✦ Journal",()->journal());button(footer,"Wallpaper",()->{Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,PetWallpaper.class));try{startActivity(i);}catch(ActivityNotFoundException e){Toast.makeText(this,"Wallpaper picker unavailable",0).show();}});root.addView(footer);setContentView(root);rebuild();}
 private void updateClock(){long now=System.currentTimeMillis();java.util.TimeZone zone=java.util.TimeZone.getDefault();String key=now/60000+":"+zone.getID()+":"+zone.getOffset(now)+":"+android.text.format.DateFormat.is24HourFormat(this);if(key.equals(clockKey))return;clockKey=key;java.util.Date date=new java.util.Date(now);java.text.DateFormat time=android.text.format.DateFormat.getTimeFormat(this);time.setTimeZone(zone);java.text.DateFormat day=java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM);day.setTimeZone(zone);String weekday=new java.text.SimpleDateFormat("EEE",java.util.Locale.getDefault()).format(date);clockLabel.setText(time.format(date)+"  •  "+weekday+", "+day.format(date)+"  •  "+PetState.dayPhase(PetState.localMinute(now,zone)));}
 private void routine(){PetState s=state();new AlertDialog.Builder(this).setTitle("Real-time routine").setMessage("Synced to your phone's clock and time zone.\nBedtime: 9 PM • Wake up: 7 AM\nSleeping restores energy and pauses hunger, happiness and care penalties. You can wake your pet for 15 minutes if needed.").setPositiveButton(s.autoSleep?"Disable auto sleep":"Enable auto sleep",(d,i)->act(25,0)).setNeutralButton(s.sleeping()?"Wake briefly":"Nap",(d,i)->act(16,0)).setNegativeButton("Close",null).show();}
 private boolean onPet(MotionEvent e){float z=Math.min(scene.getWidth()/160f,scene.getHeight()/192f);if(z<=0)return false;float x=(e.getX()-(scene.getWidth()-160*z)/2)/z,y=(e.getY()-(scene.getHeight()-192*z)/2)/z;return x>30&&x<130&&y>55&&y<165;}
 private void button(LinearLayout row,String label,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(13);b.setTypeface(Typeface.create("sans-serif-medium",0));b.setTextColor(0xfff8edff);b.setMinWidth(0);b.setMinHeight(0);b.setPadding(dp(4),0,dp(4),0);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xff414467,0xff343653});bg.setCornerRadius(dp(9));bg.setStroke(dp(1),0xff7774a6);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x55816bdb),bg,null));b.setElevation(0);b.setOnClickListener(v->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(b,lp);}
 private void lab(){new AlertDialog.Builder(this).setTitle("FOREVER LAB").setItems(new String[]{"Shop","Inventory","Creature collection","Space travel"},(d,i)->{if(i==0)shop(false);else if(i==1)shop(true);else if(i==2){PetState p=pet.snapshot();StringBuilder b=new StringBuilder();for(int n=0;n<PetState.SPECIES.length;n++)b.append((p.collection&(1<<n))!=0?PetState.SPECIES[n]:"????").append("\n");collection(p);}else{PetState p=pet.snapshot();new AlertDialog.Builder(this).setTitle("Space travel").setMessage("Biofuel: "+p.fuel+"/4").setPositiveButton("Launch",(x,y)->{if(pet.snapshot().fuel<4){Toast.makeText(this,"Collect 4 biofuel first",0).show();return;}act(12,0);zoom=0;rebuild();}).setNegativeButton("Cancel",null).show();}}).show();}
 private void collection(PetState p){ScrollView scroll=new ScrollView(this);LinearLayout grid=new LinearLayout(this);grid.setOrientation(1);grid.setBackgroundColor(0xff242447);scroll.addView(grid);for(int i=0;i<PetState.SPECIES.length;i+=3){LinearLayout row=new LinearLayout(this);grid.addView(row);for(int j=i;j<i+3;j++){PetState preview=new PetState();preview.stage=4;preview.field=(j%12)/4;preview.body=j%4;preview.variant=j/12;boolean found=(p.collection&(1<<j))!=0;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(17);ImageView im=new ImageView(this);im.setImageBitmap(art.creatureIcon(preview));im.setAlpha(found?1f:.25f);tile.addView(im,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView label=new TextView(this);label.setText(found?PetState.SPECIES[j]:"Undiscovered");label.setTextColor(0xfff6eaff);label.setTextSize(11);tile.addView(label);row.addView(tile,new LinearLayout.LayoutParams(0,-2,1));}}new AlertDialog.Builder(this).setTitle("Creature collection • "+Integer.bitCount(p.collection)+"/"+PetState.SPECIES.length).setView(scroll).setPositiveButton("Close",null).show();}
 private void shop(boolean bag){PetState p=pet.snapshot();LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(12),dp(8),dp(12),dp(8));list.setBackgroundColor(0xff242447);ScrollView sc=new ScrollView(this);sc.addView(list);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(bag?"Inventory":"Shop • "+p.coins+" coins").setView(sc).setNegativeButton("Close",null).create();
 for(int i=0;i<PetState.ITEMS.length;i++){final int item=i;boolean own=(p.owned&(1<<i))!=0;if(bag&&!own)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(4),dp(6),dp(4));ImageView icon=new ImageView(this);icon.setImageBitmap(art.itemIcon(i));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(icon,new LinearLayout.LayoutParams(dp(52),dp(52)));TextView name=new TextView(this);name.setText(PetState.ITEMS[i]+"\n"+(own?"Owned":PetState.PRICES[i]+" coins"));name.setTextColor(0xfff8edff);name.setTextSize(14);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button buy=new Button(this);buy.setText(bag?(p.equipped==i+1||p.installation==i+1?"Active":"Use"):own?"Owned":"Buy");buy.setEnabled(bag||!own);buy.setOnClickListener(v->{if(!bag&&pet.snapshot().coins<PetState.PRICES[item]){Toast.makeText(this,"Not enough coins",0).show();return;}act(bag?11:10,item);dlg.dismiss();shop(bag);});row.addView(buy,new LinearLayout.LayoutParams(dp(76),dp(48)));list.addView(row);}
 if(bag&&p.owned==0){TextView empty=new TextView(this);empty.setText("Your bag is empty. Visit the shop.");empty.setTextColor(0xfff8edff);list.addView(empty);}dlg.show();}
 private void act(int a,int v){boolean changed=pet.action(a,v);cached=null;update();if(!changed&&(a>=16||a==14||a==8))Toast.makeText(this,"Requirements not met or already completed",Toast.LENGTH_SHORT).show();}
 private void rebuild(){cached=null;zooms.setVisibility(playing?View.GONE:View.VISIBLE);footer.setVisibility(playing?View.GONE:View.VISIBLE);actions.removeAllViews();LinearLayout r=new LinearLayout(this);actions.addView(r);PetState s=pet.snapshot();displayedStage=s.stage;if(playing){button(r,"Exit & collect",()->finishGame());}
 else if(s.stage==0){button(r,"Hatch egg",()->{pet.action(0,0);rebuild();});button(r,"Land",()->act(6,0));button(r,"Water",()->act(6,1));button(r,"Sky",()->act(6,2));}
 else if(zoom==0){button(r,"Visit field",()->{zoom=1;rebuild();});}
 else if(zoom==1){button(r,"Clean field",()->act(3,0));button(r,"Land",()->act(6,0));button(r,"Water",()->act(6,1));button(r,"Sky",()->act(6,2));}
 else if(zoom==2){button(r,"Feed",()->new AlertDialog.Builder(this).setTitle("Choose food").setItems(new String[]{"Meat • 4 coins","Carrot • 2 coins","Fish","Grain • Free"},(d,i)->{PetState p=pet.snapshot();if(p.hunger>=5){Toast.makeText(this,"Pet is full",0).show();return;}if(p.coins<Economy.foodPrice(i)){Toast.makeText(this,"Not enough coins — grain is free",0).show();return;}act(14,i);}).show());button(r,"Care",()->care());button(r,"Arcade",()->chooseGame());
 if(s.stage==PetState.ADULT){LinearLayout social=new LinearLayout(this);actions.addView(social);button(social,"Playdate",()->{act(8,0);rebuild();});button(social,"Breed",()->{PetState p=pet.snapshot();if(p.friendship<4){Toast.makeText(this,"Friendship must reach 4",0).show();return;}new AlertDialog.Builder(this).setTitle("Start a new generation?").setMessage("Your pet's next egg inherits the local partner's eye and color traits.").setNegativeButton("Cancel",null).setPositiveButton("Accept",(d,i)->{pet.action(9,0);rebuild();}).show();});}}
 else {button(r,"Inspect cells",()->{act(5,0);rebuild();});button(r,"Treat",()->{if(pet.snapshot().sick)act(4,0);else Toast.makeText(this,"No sick cells detected",0).show();});}update();}
 private void chooseGame(){PetState s=state();if(s.sleeping()||s.exploring()){Toast.makeText(this,"Your pet is busy right now",0).show();return;}new AlertDialog.Builder(this).setTitle("PET ARCADE").setItems(new String[]{"Star Catch","Flappy Pet","Cloud Jump","Find My Pet"},(d,i)->{game=new Arcade(i,SystemClock.elapsedRealtime());playing=true;frameAt=SystemClock.elapsedRealtime();accum=0;rebuild();}).show();}
 private void care(){PetState s=pet.snapshot();new AlertDialog.Builder(this).setTitle("Care & bond").setItems(new String[]{"Pet / cuddle","Play together","Train","Clean habitat","Treat cells",s.sleeping()?"Wake up (15 min at night)":"Take a nap (30 min)","Cook meal (2 materials)","Give a bath"},(d,i)->{if(i<3)act(15,i);else if(i==3)act(3,0);else if(i==4){zoom=3;rebuild();}else if(i==5)act(16,0);else if(i==6)act(23,0);else act(24,0);}).show();}
 private void journal(){PetState s=pet.snapshot();new AlertDialog.Builder(this).setTitle("Adventure journal • Lv "+s.level()).setMessage(s.personality()+" personality\nEXP "+s.xp+" • Energy "+s.energy+" • Bond "+s.bond+"\nMaterials "+s.materials+" • Crystals "+s.crystals+"\n"+(s.exploring()?"Exploring — "+Math.max(1,(s.expeditionEnd-s.last)/1000)+"s left":s.pendingCoins>0?"Expedition rewards ready!":"Ready for a new adventure")).setPositiveButton("Activities",(d,i)->activities()).setNegativeButton("Close",null).show();}
 private void activities(){new AlertDialog.Builder(this).setTitle("Activities").setItems(new String[]{"Expeditions","Collect expedition loot","Daily gift","Care quests","Craft crystal (3 materials)","Secret evolution (Adult, bond 30, training 10, 3 crystals)","Petpedia"},(d,i)->{if(i==0)expeditions();else if(i==1)act(18,0);else if(i==2)act(19,0);else if(i==3)quests();else if(i==4)act(21,0);else if(i==5)act(22,0);else collection(pet.snapshot());}).show();}
 private void expeditions(){new AlertDialog.Builder(this).setTitle("Explore • Kid or older, energy 25+, fed & healthy").setItems(new String[]{"Meadow • 10 min • Lv 1","Coral ruins • 20 min • Lv 3 • 1 fuel","Starlight islands • 30 min • Lv 5 • 2 fuel"},(d,i)->act(17,i)).show();}
 private void quests(){PetState s=pet.snapshot();String[] q={"Bond with your pet","Clean habitat","Finish an expedition"};for(int i=0;i<3;i++)q[i]+=((s.claimedQuests&(1<<i))!=0?" • Claimed":(s.quests&(1<<i))!=0?" • Claim 15 coins":" • In progress");new AlertDialog.Builder(this).setTitle("Care quests").setItems(q,(d,i)->act(20,i)).show();}
 private void finishGame(){if(!playing)return;int reward=game==null?0:game.claim();playing=false;game=null;pet.action(13,reward);rebuild();Toast.makeText(this,"+"+reward+" coins",0).show();}
 private void update(){PetState s=state();if(!playing&&s.stage!=displayedStage){rebuild();return;}status.setText(s.creature()+"  •  Gen "+s.generation+"  •  "+s.fieldName()+"  •  "+s.coins+" coins · Lv "+s.level()+"\nFood "+s.hunger+"/5     Happy "+s.happy+"/10     Care "+s.mistakes+"\nEnergy "+s.energy+"%  •  Bond "+s.bond);caption.setText(playing?"Ready to play":s.stage==0?"Tap your egg to begin":zoom==3?(s.sick?"Tap to remove "+s.germs+" sick cells":s.stage==PetState.BABY?(s.nextCell()>0?"Next field cell in "+(s.nextCell()/60)+":"+(s.nextCell()%60<10?"0":"")+(s.nextCell()%60):"4 cells ready — tap to evolve"):"Diet and care record"):s.sleeping()?(s.sleepUntil>s.clockNow?"Your pet is napping":"Sleeping until 7 AM • tap clock for options"):s.exploring()?"Your pet is exploring":s.pendingCoins>0?"Adventure rewards ready in Journal":s.sick?"Your pet needs treatment in Cell":s.stage==PetState.ADULT?"Local playdate friendship: "+s.friendship+"/4":"Your pet lives even while the app is closed");scene.invalidate();}
 @Override protected void onStart(){super.onStart();active=true;cached=null;clockKey="";h.post(refresh);}
 @Override protected void onStop(){active=false;h.removeCallbacks(refresh);if(playing)finishGame();pet.flush();super.onStop();}
}
